from pathlib import Path
from pyspark.sql import SparkSession,functions as F
ROOT=Path(__file__).resolve().parents[2]; RAW=ROOT/'data/raw'; SILVER=ROOT/'data/silver/pyspark'; GOLD=ROOT/'data/gold/pyspark'; Q=ROOT/'data/quarantine/pyspark'; REPORT=ROOT/'reports/pyspark'
def spark(): return SparkSession.builder.appName('SmartManufacturingMedallion').master('local[*]').getOrCreate()
def read(s,rel): return s.read.option('header',True).option('inferSchema',False).csv(str(RAW/rel))
def write(df,p): df.coalesce(1).write.mode('overwrite').option('header',True).csv(str(p))
def txt(c,default='Unknown',case=None):
    v=F.trim(F.coalesce(F.col(c),F.lit(''))); v=F.when(v=='',default).otherwise(v); return F.upper(v) if case=='upper' else F.initcap(v) if case=='title' else v
def num(c,default=None):
    n=F.regexp_replace(F.regexp_replace(F.trim(F.coalesce(F.col(c),F.lit(''))),'\\$',''),',','').cast('double'); return F.coalesce(n,F.lit(float(default))) if default is not None else n
def ts(c):
    v=F.trim(F.coalesce(F.col(c),F.lit(''))); return F.coalesce(F.to_timestamp(v,'yyyy-MM-dd HH:mm:ss'),F.to_timestamp(v,'MM/dd/yyyy HH:mm'))
def main():
    s=spark()
    machines=(read(s,'master/machines.csv').withColumn('machine_id',txt('machine_id','','upper')).withColumn('line_id',txt('line_id','','upper')).withColumn('rated_power_kw',num('rated_power_kw')).withColumn('machine_status',txt('machine_status',case='title')).dropDuplicates(['machine_id']))
    products=(read(s,'master/products.csv').withColumn('product_id',txt('product_id','','upper')).withColumn('standard_cycle_time_sec',num('standard_cycle_time_sec')).withColumn('standard_cost',num('standard_cost')).dropDuplicates(['product_id']))
    work=(read(s,'erp/work_orders.csv').withColumn('work_order_id',txt('work_order_id','','upper')).withColumn('product_id',txt('product_id','','upper')).withColumn('line_id',txt('line_id','','upper')).withColumn('planned_qty',num('planned_qty')).dropDuplicates(['work_order_id']))
    runs=(read(s,'mes/production_runs.csv').withColumn('production_run_id',txt('production_run_id','','upper')).withColumn('work_order_id',txt('work_order_id','','upper')).withColumn('product_id',txt('product_id','','upper')).withColumn('line_id',txt('line_id','','upper')).withColumn('run_start_ts',ts('run_start_ts')).withColumn('run_end_ts',ts('run_end_ts')).withColumn('run_date',F.to_date('run_start_ts')).withColumn('good_units',num('good_units')).withColumn('scrap_units',num('scrap_units',0)).withColumn('rework_units',num('rework_units',0)).withColumn('runtime_hours',(F.col('run_end_ts').cast('long')-F.col('run_start_ts').cast('long'))/3600).dropDuplicates(['production_run_id']))
    tel=(read(s,'iot/machine_telemetry.csv').withColumn('telemetry_id',txt('telemetry_id','','upper')).withColumn('machine_id',txt('machine_id','','upper')).withColumn('reading_ts',ts('reading_ts')).withColumn('temperature_c',num('temperature_c')).withColumn('vibration_mm_s',num('vibration_mm_s')).withColumn('power_kw',num('power_kw')).withColumn('status_code',txt('status_code',case='upper')).withColumn('anomaly_flag',(F.col('temperature_c')>=75)|(F.col('vibration_mm_s')>=5)|F.col('status_code').isin('WARNING','TRIP')).dropDuplicates(['telemetry_id']))
    down=(read(s,'mes/downtime_events.csv').withColumn('downtime_event_id',txt('downtime_event_id','','upper')).withColumn('machine_id',txt('machine_id','','upper')).withColumn('line_id',txt('line_id','','upper')).withColumn('event_start_ts',ts('event_start_ts')).withColumn('event_end_ts',ts('event_end_ts')).withColumn('event_date',F.to_date('event_start_ts')).withColumn('downtime_minutes',(F.col('event_end_ts').cast('long')-F.col('event_start_ts').cast('long'))/60).dropDuplicates(['downtime_event_id']))
    for n,df in {'machines':machines,'products':products,'work_orders':work,'production_runs':runs,'machine_telemetry':tel,'downtime_events':down}.items(): write(df,SILVER/n)
    bad_tel=tel.join(machines.select('machine_id'),'machine_id','left_anti'); bad_runs=runs.join(work.select('work_order_id'),'work_order_id','left_anti'); write(bad_tel,Q/'telemetry_invalid_machine'); write(bad_runs,Q/'runs_invalid_work_order')
    vr=runs.join(work.select('work_order_id'),'work_order_id','inner').join(products.select('product_id','standard_cycle_time_sec','standard_cost'),'product_id','inner').filter(F.col('good_units').isNotNull()).withColumn('total_units',F.col('good_units')+F.col('scrap_units')+F.col('rework_units')).withColumn('scrap_rate',F.col('scrap_units')/F.col('total_units')).withColumn('ideal_runtime_hours',F.col('good_units')*F.col('standard_cycle_time_sec')/3600).withColumn('performance_ratio',F.least(F.lit(1.0),F.col('ideal_runtime_hours')/F.col('runtime_hours')))
    vtel=tel.join(machines.select('machine_id'),'machine_id','inner').filter(F.col('reading_ts').isNotNull()&F.col('power_kw').isNotNull())
    health=(vtel.groupBy('machine_id').agg(F.count('telemetry_id').alias('readings'),F.avg('temperature_c').alias('avg_temp_c'),F.max('temperature_c').alias('max_temp_c'),F.avg('vibration_mm_s').alias('avg_vibration'),F.sum(F.col('anomaly_flag').cast('int')).alias('anomaly_count')).withColumn('anomaly_rate',F.col('anomaly_count')/F.col('readings')))
    daily=(vr.groupBy('run_date','line_id').agg(F.sum('good_units').alias('good_units'),F.sum('scrap_units').alias('scrap_units'),F.sum('rework_units').alias('rework_units'),F.sum('runtime_hours').alias('runtime_hours'),F.sum('ideal_runtime_hours').alias('ideal_runtime_hours')).withColumn('quality_ratio',F.col('good_units')/(F.col('good_units')+F.col('scrap_units')+F.col('rework_units'))).withColumn('performance_ratio',F.least(F.lit(1.0),F.col('ideal_runtime_hours')/F.col('runtime_hours'))))
    dt=down.groupBy('event_date','line_id').agg(F.sum('downtime_minutes').alias('downtime_minutes')); oee=(daily.join(dt,(daily.run_date==dt.event_date)&(daily.line_id==dt.line_id),'left').drop(dt.line_id).fillna({'downtime_minutes':0}).withColumn('scheduled_minutes',F.col('runtime_hours')*60+F.col('downtime_minutes')).withColumn('availability',(F.col('runtime_hours')*60)/F.col('scheduled_minutes')).withColumn('oee',F.col('availability')*F.col('performance_ratio')*F.col('quality_ratio')))
    write(vr,GOLD/'fact_production_runs'); write(vtel,GOLD/'fact_machine_telemetry'); write(health,GOLD/'mart_machine_health'); write(oee,GOLD/'mart_daily_line_oee')
    dq=s.createDataFrame([('telemetry_invalid_machine',bad_tel.count()),('runs_invalid_work_order',bad_runs.count())],['check_name','issue_count']); write(dq,REPORT/'data_quality_report'); print('PySpark manufacturing Medallion ETL complete'); s.stop()
if __name__=='__main__': main()
